Datos de dominio.ejemplo:
# Expansión de siglas de dominio antes de indexar o consultar en RAG
DOMAIN_GLOSSARY = {"RTO": "Recovery Time Objective", "K8S": "Kubernetes"}
def expand_acronyms(query: str) -> str:
    for abbr, full in DOMAIN_GLOSSARY.items():
        query = query.replace(abbr, f"{abbr} ({full})")
    return query

