# Etiquetado débil con funciones heurísticas combinadas
def lf_reembolso(texto: str) -> int:
    return 1 if any(k in texto.lower() for k in ["devolución", "reembolso"]) else -1  # -1 = abstención

def lf_soporte_tecnico(texto: str) -> int:
    return 0 if "error 500" in texto.lower() else -1

